function cleanDrop(p){if(!p||typeof p!=='object')return null;const q=normalizeParams(p),out={geometry:q.geometry,drive:q.drive,solveFor:q.solveFor};for(const k of Object.keys(limits))out[k]=!inputIsActive(q,k)&&!Number.isFinite(q[k])?defaults[k]:q[k];const r=calculate(out);return r.valid?r.params:null;}
