function cleanCandidate(r){if(!r||typeof r.name!=='string'||!r.name.trim())return null;const m=r.mode||(r.params?.geometry?'droplet':'gradient');if(!['droplet','gradient'].includes(m))return null;const p=m==='droplet'?cleanDrop(r.params):cleanGrad(r.params);if(!p||!compute(p,m).valid)return null;return {id:typeof r.id==='string'?r.id.slice(0,120):uid(),mode:m,name:r.name.trim().slice(0,80),note:typeof r.note==='string'?r.note.slice(0,1200):'',params:p,sample:r.sample===true,created:typeof r.created==='string'?r.created:new Date().toISOString()};}
