function seed(){let added=0;for(const r of examples())if(!records.some(v=>v.id===r.id)&&records.length<80){records.push({...clone(r),created:new Date().toISOString()});added++;}for(const m of ['droplet','gradient'])if(!selections[m].length){let order=records.filter(r=>r.mode===m);if(m==='droplet')order=[...order.filter(r=>r.params.geometry==='ff'),...order.filter(r=>r.params.geometry==='t')];selections[m]=order.slice(0,4).map(r=>r.id);}return added;}
function initialize(){try{const raw=localStorage.getItem(KEY2);if(raw){const d=JSON.parse(raw);if(d.schema!==2||!Array.isArray(d.records))throw Error();designs={droplet:cleanDrop(d.designs?.droplet)||clone(defaults),gradient:cleanGrad(d.designs?.gradient)||clone(gradientDefaults)};records=d.records.map(cleanCandidate).filter(Boolean).slice(0,80);mode=d.mode==='gradient'?'gradient':'droplet';for(const m of ['droplet','gradient'])selections[m]=Array.isArray(d.selections?.[m])?[...new Set(d.selections[m])].filter(id=>records.some(r=>r.id===id&&r.mode===m)).slice(0,4):[];}else{const old=localStorage.getItem('droplab.workspace.v1');if(old){const d=JSON.parse(old);designs.droplet=cleanDrop(d.params)||clone(defaults);records=(d.records||[]).map(r=>cleanCandidate({...r,mode:'droplet'})).filter(Boolean);selections.droplet=(d.selected||[]).filter(id=>records.some(r=>r.id===id)).slice(0,4);for(const e of examples()){const i=records.findIndex(r=>r.id===e.id&&r.sample);if(i>=0)records[i]={...records[i],name:e.name,note:e.note};}}seed();}}catch{seed();notify('Stored data could not be read. Defaults are loaded; import a JSON backup to recover records.');}}
