const field=(k,l,u='',step='any',v=active()[k])=>`<label class="field">${esc(l)}<span class="input-wrap"><input type="number" name="${k}" value="${Number.isFinite(v)?v:''}" step="${step}" aria-label="${esc(l)}" aria-describedby="error-${k}"><span class="unit">${u}</span></span><small class="field-error" id="error-${k}"></small></label>`;
