if(p.type==='tree')s+=`Channels ${p.w} × ${p.h} µm; base ${p.length} mm; P1/P2/P3 ${p.p1}/${p.p2}/${p.p3}, adding ${p.pitchLength} mm each. Maximum inlet pressure ${fmt(r.pressure,4)} kPa. Isolated-channel capillary pressure ${fmt(r.capillary,3)} kPa; fill time ${r.fillTime===null?'not spontaneously wetting':fmt(r.fillTime)+' s'}. Network capillary transients are not simulated.`;
