function lineChart(points,{xLabel='',yLabel='',current=null,series2=null,yMin=null,yMax=null}={}){const good=points.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!good.length)return '<div class="chart-empty">No valid model points in this range.</div>';const xmin=Math.min(...points.map(p=>p.x)),xmax=Math.max(...points.map(p=>p.x)),all=[...good,...(series2||[]).filter(p=>Number.isFinite(p.y))],a=Math.min(...all.map(p=>p.y)),b=Math.max(...all.map(p=>p.y)),pad=(b-a)*.12||Math.abs(b)*.05||1,lo=yMin??a-pad,hi=yMax??b+pad,xx=x=>62+(x-xmin)/(xmax-xmin||1)*522,yy=y=>174-(y-lo)/(hi-lo||1)*142;let s='';for(let i=0;i<5;i++){const y=lo+(hi-lo)*i/4,x=xmin+(xmax-xmin)*i/4;s+=`<path d="M62 ${yy(y)}H584" stroke="#e4eadd" stroke-dasharray="3 5"/><text x="51" y="${yy(y)+3}" fill="#839675" font-size="9" text-anchor="end">${fmt(y,Math.abs(hi-lo)<1?3:1)}</text><text x="${xx(x)}" y="193" fill="#839675" font-size="9" text-anchor="middle">${fmt(x,Math.abs(xmax-xmin)>20?0:2)}</text>`;}const path=arr=>arr.map((p,i)=>Number.isFinite(p.y)?`${!i||!Number.isFinite(arr[i-1].y)?'M':'L'}${xx(p.x)} ${yy(p.y)}`:'').join('');if(series2)s+=`<path d="${path(series2)}" fill="none" stroke="#b8a8b2" stroke-width="1.7" stroke-dasharray="5 5"/>`;s+=`<path d="${path(points)}" fill="none" stroke="#8ca87a" stroke-width="2.4"/>`;if(current&&Number.isFinite(current.y))s+=`<circle cx="${xx(current.x)}" cy="${yy(current.y)}" r="5" fill="#6e9259" stroke="#fff" stroke-width="2"/>`;return `<svg viewBox="0 0 620 230" role="img" aria-label="${esc(yLabel+' versus '+xLabel)}">${s}<text x="62" y="15" fill="#758c65" font-size="10">${esc(yLabel)}</text><text x="323" y="218" text-anchor="middle" fill="#758c65" font-size="10">${esc(xLabel)}</text></svg>`;}
